def mean(values: list[float]) -> float:
    if not values:
        raise ValueError("empty")
    return sum(values) / len(values)

def mode(values: list[str]) -> str:
    """Return the most frequent value; ties broken by first-encountered."""
    if not values:
        raise ValueError("empty")

    for i, v in enumerate(values):
        if v is None:
            raise ValueError(f"missing value at index {i}")

    counts: dict[str, int] = {}
    first_seen: dict[str, int] = {}
    for i, v in enumerate(values):
        counts[v] = counts.get(v, 0) + 1
        if v not in first_seen:
            first_seen[v] = i

    best: str | None = None
    for v in counts:
        if (
            best is None
            or counts[v] > counts[best]
            or (counts[v] == counts[best] and first_seen[v] < first_seen[best])
        ):
            best = v
    return best  # type: ignore[return-value]
